package store

import "sync"

// KVStore is a concurrency-safe string map.
type KVStore struct {
	mu   sync.Mutex
	data map[string]string
}

func NewKVStore() *KVStore {
	return &KVStore{data: make(map[string]string)}
}

// BUG: value receivers copy the struct - and its mutex - so each call
// locks a private copy and the map is not protected at all.
func (s KVStore) Set(key, value string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[key] = value
}

func (s KVStore) Get(key string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.data[key]
	return v, ok
}

func (s KVStore) Len() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.data)
}

test_setup_files.store_race_test.go:
package store

import (
	"fmt"
	"sync"
	"testing"
)

func TestConcurrentSetGet(t *testing.T) {
	s := NewKVStore()
	var wg sync.WaitGroup
	for w := 0; w < 8; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			for i := 0; i < 500; i++ {
				key := fmt.Sprintf("k-%d-%d", w, i)
				s.Set(key, "v")
				if _, ok := s.Get(key); !ok {
					t.Errorf("key %s vanished", key)
				}
			}
		}(w)
	}
	wg.Wait()
	if s.Len() != 4000 {
		t.Fatalf("Len() = %d, want 4000", s.Len())
	}
}

